const validationResult = (valid, error = null) => 
  valid ? { valid: true } : { valid: false, error };

export function validateTodoText(text) {
  if (typeof text !== 'string') {
    return validationResult(false, 'text must be a string');
  }
  const trimmed = text.trim();
  if (trimmed.length === 0) {
    return validationResult(false, 'text must not be empty');
  }
  if (trimmed.length > MAX_TODO_TEXT_LENGTH) {
    return validationResult(false, `text must be at most ${MAX_TODO_TEXT_LENGTH} characters`);
  }
  return validationResult(true);
}

